<?php
namespace App\Services;
class Documents {
 public static function html(array $d,string $type,bool $watermark):string {
 $e=fn($s)=>htmlspecialchars((string)($s??''),ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');$p=$d['personal']??[];$accent=preg_match('/^#[a-f0-9]{6}$/i',$d['accent']??'')?$d['accent']:'#1557d2';$font=($d['font']??'')==='Georgia'?'DejaVu Serif':'DejaVu Sans';$photo='';if(!empty($d['photo'])&&($d['showPhoto']??true)&&preg_match('#^data:image/(jpeg|png|webp);base64,[A-Za-z0-9+/=]+$#',$d['photo'])&&strlen($d['photo'])<200000)$photo='<img class="photo" src="'.$d['photo'].'">';
 $css="@page{margin:34pt}body{font-family:'$font';font-size:10pt;line-height:1.45;color:#17263a}h1{font-size:25pt;line-height:1.1;margin:0 0 5pt;color:$accent}h2{font-size:11pt;letter-spacing:.6pt;color:$accent;border-bottom:1pt solid $accent;padding-bottom:4pt;margin:15pt 0 7pt}p{margin:5pt 0}header{border-bottom:3pt solid $accent;padding:12pt 0 16pt}.role{font-size:13pt}.contact{font-size:9pt;color:#435065}ul{padding-left:14pt;margin:4pt 0 10pt}li{margin-bottom:4pt}.row{page-break-inside:avoid}.meta{font-size:9pt;color:#536272}.photo{float:right;width:65pt;height:65pt;border-radius:8pt}.watermark{position:fixed;bottom:-18pt;left:0;right:0;text-align:center;color:#6c7583;font-size:9pt}.letter p{margin-bottom:13pt}.columns{width:100%;border-collapse:collapse}.columns td{vertical-align:top}.side{width:27%;background:#edf1f7;padding:12pt}.main{padding-right:16pt}.ref{font-size:9pt;color:#627180}";
 $h='<!doctype html><html><head><meta charset="utf-8"><style>'.$css.'</style></head><body>'.($watermark?'<div class="watermark">'.$e(Settings::get('features')['watermarkText']).'</div>':'').'<header>'.$photo.'<h1>'.$e($p['name']).'</h1>'.(!empty($p['role'])?'<p class="role">'.$e($p['role']).'</p>':'').'<p class="contact">'.$e(implode(' · ',array_filter(array_intersect_key($p,array_flip(['email','phone','city','linkedin','portfolio']))))).'</p></header>';
 if($type==='letter'){$h.='<main class="letter"><p>'.$e($d['date']??'').'</p><p>'.$e($d['recipient']??'Hiring Manager').'<br>'.$e($d['company']??'').'</p><h2>'.$e($d['subject']??'').'</h2><p>'.$e($d['salutation']??'Dear Hiring Manager,').'</p>';foreach(['opening','evidence','motivation','closing'] as $k)if(!empty($d[$k]))$h.='<p>'.nl2br($e($d[$k])).'</p>';$h.='<p>'.$e($d['signoff']??'Kind regards,').'<br>'.$e($p['name']).'</p></main>';}else{
 $labels=['summary'=>'Profile','experience'=>'Experience','education'=>'Education','projects'=>'Projects','skills'=>'Skills','certifications'=>'Certifications','languages'=>'Languages','awards'=>'Awards & volunteering'];$parts=[];$bullet=fn($s)=>'<ul>'.implode('',array_map(fn($l)=>'<li>'.$e(preg_replace('/^[•*-]\s*/u','',trim($l))).'</li>',array_filter(explode("\n",$s??'')))).'</ul>';
 foreach(['summary','skills','languages','awards'] as $k)if(!empty($d[$k]))$parts[$k]='<p>'.nl2br($e($d[$k])).'</p>';
 foreach(['experience','education','projects','certifications'] as $k){$parts[$k]='';foreach($d[$k]??[] as $row){$heading=$row['role']??$row['degree']??$row['name']??'';$meta=array_filter([$row['company']??$row['school']??$row['issuer']??'',$row['city']??'',$row['tools']??'',$row['link']??'',trim(($row['start']??'').' – '.(($row['current']??false)?'Present':($row['end']??$row['date']??'')),' –')]);$parts[$k].='<div class="row"><b>'.$e($heading).'</b><p class="meta">'.$e(implode(' · ',$meta)).'</p>'.$bullet($row['bullets']??$row['details']??'').'</div>';}}
 $main='';$side='';$columns=preg_match('/sidebar|suite-(prism|folio|vector|forma)/',$d['template']??'');foreach($d['order']??array_keys($labels) as $k){if(!isset($labels[$k])||in_array($k,$d['hidden']??[])||empty($parts[$k]))continue;$block='<section><h2>'.$e($d['sectionLabels'][$k]??$labels[$k]).'</h2>'.$parts[$k].'</section>';if($columns&&in_array($k,['skills','languages','certifications']))$side.=$block;else $main.=$block;}$h.=$columns?'<table class="columns"><tr><td class="main">'.$main.'</td><td class="side">'.$side.'</td></tr></table>':$main;
 }return $h.'</body></html>';
 }
 public static function word(array $d,string $type,bool $watermark):\PhpOffice\PhpWord\PhpWord {\PhpOffice\PhpWord\Settings::setOutputEscapingEnabled(true);$word=new \PhpOffice\PhpWord\PhpWord();$word->setDefaultFontName('Arial');$word->setDefaultFontSize(10);$s=$word->addSection(['marginTop'=>720,'marginBottom'=>720]);$s->addText($d['personal']['name']??'',['bold'=>true,'size'=>24,'color'=>ltrim($d['accent']??'#1557d2','#')]);$s->addText(implode(' · ',array_filter($d['personal']??[])));if($watermark)$s->addFooter()->addText(Settings::get('features')['watermarkText']);if($type==='letter'){foreach(['date','recipient','company','subject','salutation','opening','evidence','motivation','closing','signoff'] as $key)if(!empty($d[$key]))$s->addText($d[$key]);}else{foreach($d['order']??[] as $k){if(in_array($k,$d['hidden']??[])||empty($d[$k]))continue;$s->addText(ucfirst($k),['bold'=>true,'size'=>12]);if(is_array($d[$k]))foreach($d[$k] as $row){foreach($row as $field=>$value)if(!in_array($field,['id','current'])&&is_string($value)&&$value!=='')$s->addText($value);}else $s->addText($d[$k]);}}return $word;}
}
